<?php defined('_JEXEC') or die;use Joomla\CMS\HTML\HTMLHelper;use Joomla\CMS\Router\Route; ?><div class="container-fluid"><h1>Vehicle Inspections</h1><div class="card mb-4"><div class="card-body"><form action="<?php echo Route::_('index.php?option=com_kaarbooking&task=vehicles.inspect'); ?>" method="post" class="row g-3"><div class="col-md-3"><select class="form-select" name="vehicle_id" required><option value="">Choose vehicle</option><?php foreach($this->vehicles as $v): ?><option value="<?php echo $v['id']; ?>"><?php echo htmlspecialchars($v['registration_number'],ENT_QUOTES,'UTF-8'); ?></option><?php endforeach; ?></select></div><div class="col-md-3"><select class="form-select" name="driver_id"><option value="">No assigned driver</option><?php foreach($this->drivers as $d): ?><option value="<?php echo $d['id']; ?>"><?php echo htmlspecialchars($d['display_name'],ENT_QUOTES,'UTF-8'); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><input class="form-control" type="date" name="inspection_date" required></div><div class="col-md-2"><select class="form-select" name="result"><option value="passed">Passed</option><option value="conditional">Conditional</option><option value="failed">Failed</option></select></div><div class="col-md-2"><input class="form-control" type="number" min="0" step=".1" name="odometer_km" placeholder="Odometer"></div><div class="col-md-2"><input class="form-control" type="date" name="next_due_date"></div><div class="col-12 d-flex gap-3"><label><input type="checkbox" name="check_identity" value="1"> Identity</label><label><input type="checkbox" name="check_roadworthy" value="1"> Roadworthy</label><label><input type="checkbox" name="check_safety" value="1"> Safety</label><label><input type="checkbox" name="check_cleanliness" value="1"> Cleanliness</label></div><div class="col-md-8"><textarea class="form-control" name="notes" placeholder="Notes"></textarea></div><div class="col-md-3"><button class="btn btn-primary">Record inspection</button></div><?php echo HTMLHelper::_('form.token'); ?></form></div></div><form method="get" class="row g-2 mb-3"><input type="hidden" name="option" value="com_kaarbooking"><input type="hidden" name="view" value="inspections"><div class="col-md-3"><input class="form-control" name="filter_search" value="<?php echo htmlspecialchars($this->filters['search'],ENT_QUOTES,'UTF-8'); ?>" placeholder="Registration, make, model, driver or organization"></div><div class="col-md-2"><select class="form-select" name="filter_driver"><option value="">All drivers</option><?php foreach($this->drivers as $d): ?><option value="<?php echo $d['id']; ?>" <?php echo $this->filters['driver']==$d['id']?'selected':''; ?>><?php echo htmlspecialchars($d['display_name'],ENT_QUOTES,'UTF-8'); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><select class="form-select" name="filter_company"><option value="">All organizations</option><?php foreach($this->companies as $c): ?><option value="<?php echo $c['id']; ?>" <?php echo $this->filters['company']==$c['id']?'selected':''; ?>><?php echo htmlspecialchars($c['name'],ENT_QUOTES,'UTF-8'); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><select class="form-select" name="filter_type"><option value="">All vehicle types</option><?php foreach($this->types as $t): ?><option value="<?php echo $t['id']; ?>" <?php echo $this->filters['type']==$t['id']?'selected':''; ?>><?php echo htmlspecialchars($t['title'],ENT_QUOTES,'UTF-8'); ?></option><?php endforeach; ?></select></div><div class="col-md-1"><select class="form-select" name="filter_result"><option value="">All results</option><option>passed</option><option>conditional</option><option>failed</option></select></div><div class="col-md-2"><button class="btn btn-secondary">Filter</button> <a class="btn btn-link" href="<?php echo Route::_('index.php?option=com_kaarbooking&view=inspections'); ?>">Clear</a></div></form><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Vehicle</th><th>Make/model</th><th>Type</th><th>Organization</th><th>Driver</th><th>Date</th><th>Inspector</th><th>Result</th><th>Next due</th></tr></thead><tbody><?php foreach($this->items as $i): ?><tr><td><?php echo htmlspecialchars($i['registration_number'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars(trim($i['make'].' '.$i['model']),ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($i['type_title']??'',ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($i['company_name']??'Operator',ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($i['driver_name']??'—',ENT_QUOTES,'UTF-8'); ?></td><td><?php echo $i['inspection_date']; ?></td><td><?php echo htmlspecialchars($i['inspector_name']??'',ENT_QUOTES,'UTF-8'); ?></td><td><?php echo $i['result']; ?></td><td><?php echo $i['next_due_date']??'—'; ?></td></tr><?php endforeach; ?><?php if(!$this->items): ?><tr><td colspan="9">No inspections match the filters.</td></tr><?php endif; ?></tbody></table></div></div>
